from pathlib import Path
import shutil,json,hashlib,subprocess,re
root=Path(__file__).resolve().parents[3];doc=Path(__file__).resolve().parent
source=Path('/workspace/halfsword-black-king');pub=Path('/workspace/halfsword-weapons-preview/public/encounters');dest=pub/'wander-heroes-20261023';dest.mkdir(parents=True,exist_ok=True)
# One exact shared preview build; no changes to the normal public game's source.
def copy_game(src,dst,prefix,extra=''):
 if dst.exists():shutil.rmtree(dst)
 shutil.copytree(src,dst,ignore=lambda p,n:[x for x in n if Path(p)==src and x in {'encounters','corr','r2p','support','wb'}])
 isolate="""<script>(()=>{const prefix='__PREFIX__';let native;try{native=window.localStorage}catch{}const memory=new Map(),keys=()=>native?Object.keys(native).filter(k=>k.startsWith(prefix)).map(k=>k.slice(prefix.length)):[...memory.keys()];const isolated={getItem(k){try{return native?native.getItem(prefix+String(k)):(memory.get(String(k))??null)}catch{return memory.get(String(k))??null}},setItem(k,v){k=String(k);v=String(v);memory.set(k,v);try{native?.setItem(prefix+k,v)}catch{}},removeItem(k){memory.delete(String(k));try{native?.removeItem(prefix+String(k))}catch{}},clear(){for(const k of keys())this.removeItem(k)},key(i){return keys()[i]??null},get length(){return keys().length}};Object.defineProperty(window,'localStorage',{value:isolated});__EXTRA__})();</script>""".replace('__PREFIX__',prefix).replace('__EXTRA__',extra)
 p=dst/'index.html';p.write_text(p.read_text().replace('<head>','<head>'+isolate,1))
copy_game(root/'dist',dest/'game','stillness.preview.heroes.20261023:')
for id in ['black_king','sebastian','white_scale']:shutil.copy2(source/'docs/design/olivier_20261023/front'/(id+'.png'),dest/(id+'.png'))
for view in ['angle','rear']:shutil.copy2(source/'docs/design/olivier_20261023'/view/'black_king.png',dest/(view+'.png'))
