shutil.copy2(source/'docs/design/black_king_helmet_20261023/front/black_king.png',dest/'before.png')
sha=subprocess.check_output(['git','rev-parse','HEAD'],cwd=root,text=True).strip();manifest={'featureCommit':sha,'receiverBase':'fae538a8ad7f46b01b155809ce49c8d3ed238c64','sourceFiles':{str(p.relative_to(root)):hashlib.sha256(p.read_bytes()).hexdigest()for p in sorted((root/'src').glob('*.js'))}}
(dest/'source.json').write_text(json.dumps(manifest,indent=2)+'\n')
style='''<style>*{box-sizing:border-box}body{margin:0;background:#211f1b;color:#dfd1b8;font:16px/1.8 system-ui,sans-serif}main{max-width:1100px;margin:auto;padding:24px 18px 55px}h1{font-size:36px;font-weight:500}h2{font-size:23px;font-weight:500;margin-top:34px}p,figcaption{color:#bfb39e}a{color:inherit}nav{display:flex;gap:10px;flex-wrap:wrap;margin:22px 0}nav a{padding:10px 16px;background:#332e25;border:1px solid #887548;text-decoration:none}figure{margin:16px 0}img{display:block;width:100%;height:auto}figcaption{font-size:13px;margin-top:6px}.pair,.three{display:grid;gap:14px;grid-template-columns:1fr 1fr}.three{grid-template-columns:repeat(3,1fr)}.note{font-size:14px}summary{cursor:pointer}@media(max-width:600px){main{padding:18px 12px}h1{font-size:28px}.three{grid-template-columns:1fr 1fr}.pair,.three{gap:7px}nav a{flex:1 0 44%;text-align:center;padding:9px 7px}}</style>'''
def fig(img,cap):return f'<figure><a href="{img}"><img src="{img}" alt="{cap}"></a><figcaption>{cap}</figcaption></figure>'
def game(id):return 'game/?test=1&weapon=longsword&foe='+id+'&stage=cathedral&uniqueStage=5&nosw=1'
html='<!doctype html><html lang="ko"><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>올리비에 · 롤랑 · 방랑 | Stillness</title>'+style+'<main><h1>올리비에</h1><p>롤랑의 오랜 벗이자 오른팔. 짙은 피부와 풍성한 검은 수염, 곱슬 중단발. 투구를 벗고 먹빛 갑옷과 차분한 황토빛 망토를 입었습니다.</p>'+fig('game-detail.png','실제 게임 화면 · 카메라를 가까이 옮겨 촬영')+f'<nav><a href="{game("black_king")}">올리비에와 대련</a><a href="game/?test=1&hero=black_king&weapon=tizona&foe=bran&foeWeapon=tree_branch&stage=cathedral&uniqueStage=5&nosw=1">올리비에 조작</a><a href="../wander-20261023/">방랑 체험</a></nav><h2>투구와 갑옷의 변화</h2><div class="pair">'+fig('before.png','이전 · 폐쇄 투구와 밝은 노랑')+fig('black_king.png','수정 · 같은 축척·조명의 모델 관찰 화면')+'</div><p class="note">눈은 앞선 버전에서 높이 10mm로 작아져 있었습니다. 기본 크기인 15mm로 복원했습니다. 투구를 벗으면서 머리의 투구 방어도도 제거했습니다.</p><div class="pair">'+fig('angle.png','모델 관찰 · 사선')+fig('rear.png','모델 관찰 · 뒤쪽, 짧은 어깨 망토')+'</div><h2 id="roland">롤랑과 백린의 전사</h2><div class="pair">'+fig('sebastian.png','롤랑 · 세바스티앙에서 개명. 기존 외형 유지')+fig('white_scale.png','백린의 전사 · 일본 검술을 수련한 몽골 전사')+f'</div><nav><a href="{game("sebastian")}">롤랑과 대련</a><a href="{game("white_scale")}">몽골 전사와 대련</a></nav><p class="note">모델 관찰 화면은 실제 게임 모델을 같은 조명과 자세로 촬영했습니다. 대성당은 외형 검토용 대련장입니다. 검토판 저장은 기존 게임과 분리됩니다.</p></main></html>'
(dest/'index.html').write_text(html)
