extra="""const key='stillness.lobby.progress.v1',bosses={artoria:'excalibur',sebastian:'tizona',white_scale:'muramasa'},selected=new URLSearchParams(location.search).get('opponent');let value;try{value=JSON.parse(isolated.getItem(key))}catch{}if(!value){value={version:1,coins:100,heads:0,acquisitions:[],titles:[],title:'여행자',wander:{unlocked:true,legacyChecked:true,cleared:__STAGES__,run:null}};isolated.setItem('stillness.journey.checkpoint.v1',JSON.stringify({version:1,stage:'poseidon'}));}if(bosses[selected])value.wander.run={id:crypto.randomUUID(),round:1,wins:0,stage:'poseidon',foe:selected,foeWeapon:bosses[selected],weapon:null,cards:null,lastWeapon:null,status:'active',headTaken:false,reward:null};isolated.setItem(key,JSON.stringify(value));history.replaceState(null,'',location.pathname+'?title=1&nosw=1');""".replace('__STAGES__',json.dumps(stages))
